def heap_push(H, val, elt):
    H.append((val, elt))
    i = len(H) - 1
    while i > 1 and H[i // 2][0] > val:
        H[i] = H[i // 2]
        i = i // 2
    H[i] = (val, elt)

def heap_pop(H):
    n = len(H) - 1
    if n == 0:
        raise Exception("empty heap")
    top = H[1]
    last = H.pop()
    n = n - 1
    if n > 0:
        i = 1
        ok = False
        while 2 * i <= n and not ok:
            j = 2 * i
            if j + 1 <= n and H[j + 1][0] < H[j][0]:
                j = j + 1
            if H[j][0] < last[0]:
                H[i] = H[j]
                i = j
            else:
                ok = True
        H[i] = last
    return top

def heap_sort(L):
    H = [None]
    for i in range(len(L)):
        heap_push(H, L[i][0], L[i][1])
    R = []
    for i in range(len(L)):
        R.append(heap_pop(H))
    return R
```

