def sift_down(T, i, n):
    """moves T[i] down until its sons are greater (T[1..n] perfect tree)"""
    e = T[i]
    ok = False
    while 2 * i <= n and not ok:
        j = 2 * i
        if j + 1 <= n and T[j + 1][0] < T[j][0]:
            j = j + 1
        if T[j][0] < e[0]:
            T[i] = T[j]
            i = j
        else:
            ok = True
    T[i] = e

def heapify(T):
    n = len(T) - 1
    for i in range(n // 2, 0, -1):
        sift_down(T, i, n)
```

