def cut(x, B):
    """splits the BST B into (L, R): keys <= x in L, keys > x in R"""
    if B == None:
        return (None, None)
    if x < B.key:
        (L, R) = cut(x, B.left)
        B.left = R
        return (L, B)
    else:
        (L, R) = cut(x, B.right)
        B.right = L
        return (B, R)

def addRoot(x, B):
    (L, R) = cut(x, B)
    return BinTree(x, L, R)
```

