    while B.right != None:
        B = B.right
    return B.key

def __deleteAVL(x, A):
    """returns (A without x, True if the height of A has changed)"""
    if A == None:
        return (None, False)
    if x == A.key:
        if A.left != None and A.right != None:
            A.key = maxBST(A.left)
            x = A.key       # deleted below, in the left subtree
        elif A.left == None:
            return (A.right, True)
        else:
