            else:
                A = lr(A)
        return (A, A.bal == 0)
    else:
        (A.right, dh) = __deleteAVL(x, A.right)
        if not dh:
            return (A, False)
        A.bal = A.bal + 1
        if A.bal == 2:
            if A.left.bal == -1:
                A = lrr(A)
            else:
                A = rr(A)
        return (A, A.bal == 0)

