```python
def __list2avl(L, left, right):
    """AVL of L[left..right], and its height"""
    if left > right:
        return (None, -1)
    mid = (left + right) // 2
    B = AVL(L[mid], None, None, 0)
    (B.left, hl) = __list2avl(L, left, mid - 1)
    (B.right, hr) = __list2avl(L, mid + 1, right)
    B.bal = hl - hr
    return (B, 1 + max(hl, hr))

def list2avl(L):
    (A, h) = __list2avl(L, 0, len(L) - 1)
    return A
```

