def bstMystery(x, B):
    # first part
    P = None
    while B != None and x != B.key:
        if x < B.key:
            P = B
            B = B.left
        else:
            B = B.right
    if B == None:
        return None
    # second part
    if B.right == None:
        return P
    else:
        B = B.right
        while B.left != None:
            B = B.left
        return B

def call(x, B):
    p = bstMystery(x, B)
    if p == None:
        return None
    else:
        return p.key
