def addBSTSize(x, A):
    """adds x in leaf if absent: returns (tree, True if x was added)"""
    if A == None:
        return (BinTreeSize(x, None, None, 1), True)
    if x < A.key:
        (A.left, insert) = addBSTSize(x, A.left)
    elif x > A.key:
