def rebalancing(A):
    """A not empty, A.bal in [-2, 2]: rotation if needed;
    returns (tree, True if the rotation changed the height)"""
    if abs(A.bal) < 2:
        return (A, False)
    if A.bal == 2:
        if A.left.bal == 1:
            return (rr(A), True)
        elif A.left.bal == 0:
            return (rr(A), False)
        else:
            return (lrr(A), True)
    else:
        if A.right.bal == -1:
            return (lr(A), True)
        elif A.right.bal == 0:
            return (lr(A), False)
        else:
            return (rlr(A), True)
