def myst(B, a):
    if B == None:
        return 0
    else:
        b = myst(B.right, a)
        if b == 0:
            B.key = B.key + a
        B.key = B.key + b
        b = myst(B.left, B.key)
        if b == 0:
            return B.key
        else:
            return b

def mystery(B):
    myst(B, 0)
